/* THE HYBRID: dependency-free, responsive UI for your local-first training tracker. */
'use strict';
let model=null, view='dashboard', selectedDate=localISO(), selectedDay=dayFor(selectedDate);
let focusExercise='', toastTimer=null, syncing=false;
const browserMode=window.HYBRID_STORAGE_MODE==='browser';
const sheetsMode=window.HYBRID_STORAGE_MODE==='sheets';
let lastSheetSave=null,pendingSheetWrites=0;
function getAutoSync(){try{return localStorage.getItem('hybrid-auto-sync')==='yes';}catch{return false;}}
function setAutoSync(value){try{localStorage.setItem('hybrid-auto-sync',value?'yes':'no');}catch{}}
const $=s=>document.querySelector(s);
const all=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function localISO(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function dayFor(iso){return iso?window.HybridSchedule.dayFor(iso):null;}
function weekOf(iso){return window.HybridSchedule.weekOf(model.plan,iso);}
function friendly(iso){return new Date(iso+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});}
function shortDate(iso){return new Date(iso+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'});}
function weekDates(){return window.HybridSchedule.weekDates(model.plan,selectedDate);}
function getDay(day){return model.plan.days.find(d=>d.day===day)||null;}
function recs(kind){return model?.records?.[kind]||[];}
function todaySets(){const ids=new Set(getDay(selectedDay)?.exercises.map(ex=>ex.id)||[]);return recs('sets').filter(s=>s.date===selectedDate&&ids.has(s.exercise_id));}
function done(s){return String(s?.completed).toUpperCase()==='TRUE';}
function validNum(v){return v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v));}
function num(v){return validNum(v)?Number(v):0;}
function nfmt(x){return Math.round(x).toLocaleString('en-GB');}
function weekdayTarget(day){return getDay(day)?.exercises.reduce((a,e)=>a+e.sets,0)||0;}
function wkDone(day,dates){const workout=getDay(day),index=model.plan.days.findIndex(d=>d.day===day),ids=new Set(workout?.exercises.map(ex=>ex.id)||[]);return recs('sets').filter(s=>done(s)&&s.date===dates[index]&&ids.has(s.exercise_id)).length;}
function capWeek(s){return s===1?'FOUNDATION':s===2?'BUILD':s===3?'INTENSITY':'CONSOLIDATE';}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3700);}
function connectedDashboardUrl(){const url=window.HYBRID_SHEETS_DASHBOARD_URL;return typeof url==='string'&&/^https:\/\/script\.google\.com\/macros\/s\/[\w-]+\/exec(?:[?#].*)?$/.test(url)?url:'';}
function configureBrowserUI(){if(!browserMode&&!sheetsMode)return;all('[data-settings-label]').forEach(label=>label.textContent=sheetsMode?'Google Sheets':'Backup & data');const action=$('.top-actions [data-action]');if(action){action.dataset.action=sheetsMode?'refresh-sheets':'export';action.innerHTML=sheetsMode?'↻ <span>Refresh Sheets</span>':'↓ <span>Export backup</span>';action.setAttribute('aria-label',sheetsMode?'Refresh Google Sheets':'Export JSON backup');action.hidden=browserMode&&Boolean(connectedDashboardUrl());}const link=$('#connected-dashboard-link');if(link){link.hidden=!browserMode||!connectedDashboardUrl();if(!link.hidden)link.href=connectedDashboardUrl();}if(sheetsMode){const pill=$('#storage-mode-pill');if(pill)pill.innerHTML='<span class="green-dot"></span> DIRECT TO GOOGLE SHEETS';}}
async function api(path,opts={}){if(sheetsMode){const method=(opts.method||'GET').toUpperCase(),mutation=method!=='GET';if(mutation&&syncing)throw Error('Wait for Google Sheets to finish refreshing, then save your changes.');if(mutation)pendingSheetWrites++;try{return await new Promise((resolve,reject)=>{const run=window.google?.script?.run;if(!run){reject(Error('Open the connected dashboard from its Google Apps Script link to access your workbook.'));return;}run.withSuccessHandler(data=>{if(data?.error)reject(Error(data.error));else resolve(data);}).withFailureHandler(error=>reject(Error(error?.message||String(error)||'Google Sheets request failed.'))).hybridRequest({path,method,body:opts.body??null});});}finally{if(mutation)pendingSheetWrites--;}}if(browserMode)return window.HybridBrowserStorage.request(path,opts);const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}});let data;try{data=await r.json();}catch{throw Error('Unexpected server response.');}if(!r.ok)throw Error(data.error||`Server error ${r.status}`);return data;}
async function load(){model=await api('/api/state');selectedDay=dayFor(selectedDate);updateTop();draw();}
function updateTop(){if(!model)return;$('#header-date').textContent=new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#sync-state').innerHTML=sheetsMode?`<span class="pulse"></span>${lastSheetSave?'Saved to Google Sheets · '+esc(new Date(lastSheetSave).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})):'Connected to Google Sheets'}`:browserMode?'<span class="pulse"></span> Saved in this browser':model.connected?`<span class="pulse"></span>${model.last_sync?'Synced '+esc(new Date(model.last_sync).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})):'Google connected'}`:'<span class="pulse"></span> Offline ready';configureBrowserUI();}
function nav(next){view=next;location.hash=next;all('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===next));draw();window.scrollTo({top:0,behavior:'instant'});}
function draw(){if(!model)return;const frames={dashboard:dashboard,train:train,progress:progress,journal:journal,settings:settings};$('#view').innerHTML=(frames[view]||dashboard)();}
function button(label,navTarget,extra=''){return `<button class="btn ${extra}" data-nav="${navTarget}">${label}</button>`;}
function kpi(title,value,tail){return `<div class="stat"><div class="eyebrow">${title}</div><div class="value">${value}</div><div class="tail">${tail}</div></div>`;}
function dashboard(){
  const next=window.HybridSchedule.nextSession(model.plan,localISO()),curr=next.day;
  const dates=weekDates(),cycle=window.HybridSchedule.cycleDates(model.plan,selectedDate),exerciseIds=new Set(model.plan.days.flatMap(day=>day.exercises.map(ex=>ex.id)));
  const weekSets=recs('sets').filter(s=>cycle.includes(s.date)&&exerciseIds.has(s.exercise_id)&&done(s));
  const cardio=recs('cardio').filter(c=>cycle.includes(c.date));
  const sessions=new Set(weekSets.map(x=>x.date)).size;
  const vol=weekSets.reduce((a,x)=>a+num(x.reps)*num(x.weight_kg),0);
  const cardioMin=cardio.reduce((a,x)=>a+num(x.minutes),0);
  const recent=[...new Set(recs('sets').filter(done).map(s=>s.date))].sort().reverse().slice(0,5);
  return `<div class="page-head"><div><div class="overline">YOUR PERSONAL TRAINING HQ</div><h1>Own the process.</h1><p class="page-sub">Five lifting days. Focused sets. Enough cardio to improve conditioning without sacrificing recovery.</p></div><span class="tag">WEEK ${weekOf(selectedDate)} / 4</span></div>
  <section class="hero"><div class="hero-content"><div class="overline" style="color:#d9efbf">BEAR × MENTZER × ARNOLD</div><h2>EVERY REP <em>COUNTS.</em></h2><p>Log the load. Log the reps. Win the next session. Training works best when progress is measurable.</p>${button('Start logging →','train')}</div><div class="hero-side"><div class="big-num">0${weekOf(selectedDate)}</div><small>OF 04 WEEKS</small></div></section>
  <div class="stats">${kpi('COMPLETED SETS',nfmt(weekSets.length),'Current Mon–Sun week')}${kpi('LIFTING DAYS',sessions,'Days with recorded sets')}${kpi('STAIRMASTER + CARDIO',nfmt(cardioMin)+'<span style="font-size:17px">m</span>','Minutes this cycle')}${kpi('TRAINING VOLUME',nfmt(vol),'kg × reps this cycle')}</div>
  <div class="content-grid"><section class="card"><div class="card-head"><div><h3>Your weekly schedule</h3><p class="hint" style="margin:5px 0 0">${esc(shortDate(cycle[0]))} – ${esc(shortDate(cycle[6]))} · choose a workout to log it</p></div><span class="mini-badge">MON – SUN</span></div>
  <div class="schedule-list">${cycle.map(date=>{const day=dayFor(date),d=getDay(day);if(!d)return `<div class="schedule-row recovery"><div class="schedule-date"><strong>${day.slice(0,3).toUpperCase()}</strong><small>${esc(shortDate(date))}</small></div><div class="schedule-workout"><strong>Rest & recovery</strong><small>Sleep, refuel and recover</small></div><span class="tag neutral">REST</span></div>`;if(date<model.plan.start_date)return `<div class="schedule-row recovery"><div class="schedule-date"><strong>${esc(d.short)}</strong><small>${esc(shortDate(date))}</small></div><div class="schedule-workout"><strong>${esc(d.focus)}</strong><small>Before your programme starts on ${esc(shortDate(model.plan.start_date))}</small></div><span class="schedule-count" style="color:var(--muted)">–</span></div>`;const complete=wkDone(day,dates),target=weekdayTarget(day);return `<button class="schedule-row ${date===selectedDate?'active':''}" data-jump-day="${day}" aria-label="Open ${esc(day)} ${esc(shortDate(date))}: ${esc(d.focus)}"><div class="schedule-date"><strong>${esc(d.short)}</strong><small>${esc(shortDate(date))}</small></div><div class="schedule-workout"><strong>${esc(d.focus)}</strong><small>${d.cardio_target} min StairMaster · ${esc(d.cardio_intensity.toLowerCase())}</small></div><span class="schedule-count">${complete}/${target}<small>sets</small></span></button>`;}).join('')}</div>
  <hr class="separator"><div class="card-head"><h3>Next session</h3><span class="tag neutral">${esc(curr.short)} · ${esc(shortDate(next.date))}</span></div><div style="font-size:25px;font-weight:850;letter-spacing:-.04em">${esc(curr.focus)}</div><p class="hint">${curr.exercises.length} movements · ${weekdayTarget(curr.day)} prescribed sets · ${curr.cardio_target} min StairMaster (${esc(curr.cardio_intensity.toLowerCase())})</p><button class="btn btn-outline btn-sm" data-session-date="${next.date}">Open workout →</button></section>
  <section class="card"><div class="card-head"><h3>Recent training</h3><span class="mini-badge">LIVE LOGS</span></div>${recent.length?`<div class="session-list">${recent.map(date=>{const rows=recs('sets').filter(x=>x.date===date&&done(x));return `<div class="session-line"><div><strong>${friendly(date)}</strong><small>${esc(dayFor(date))} · ${rows.length} sets recorded</small></div><span class="green-text" style="font-weight:800">✓ Logged</span></div>`}).join('')}</div>`:'<div class="no-data">No sets logged yet.<br>Open Training log and save your first set.</div>'}
  <hr class="separator"><div class="overline">PROGRESSION RULE</div><p class="hint">Reach the top of the rep range with clean technique? Increase the weight by the smallest manageable increment next time. No need to force failure on every set.</p></section></div>`;
}
function setId(date,id,n){return `${date}__${id}__${n}`;}
function getSets(date,id){return recs('sets').filter(s=>s.date===date&&s.exercise_id===id).sort((a,b)=>num(a.set_number)-num(b.set_number));}
function exerciseCard(ex,i,week){const rows=getSets(selectedDate,ex.id);const target=ex.sets;const count=Math.max(target,...rows.map(r=>num(r.set_number)),0);const complete=rows.filter(done).length;
 const setRows=Array.from({length:count},(_,j)=>{const n=j+1,r=rows.find(x=>num(x.set_number)===n)||{};return `<div class="set-row" data-set="${n}" data-exid="${esc(ex.id)}"><div class="set-num">${n}</div><input class="field" aria-label="${esc(ex.name)} set ${n} weight in kilograms" type="number" min="0" max="9999" step="0.5" placeholder="kg" data-field="weight_kg" value="${esc(r.weight_kg??'')}"><input class="field" aria-label="${esc(ex.name)} set ${n} reps" type="number" min="0" max="9999" step="1" placeholder="reps" data-field="reps" value="${esc(r.reps??'')}"><input class="field" aria-label="Reps in reserve" type="number" min="0" max="10" step="1" placeholder="RIR" data-field="rir" value="${esc(r.rir??'')}"><input class="set-check" aria-label="Complete set ${n}" type="checkbox" data-field="completed" ${done(r)?'checked':''}><button class="set-save" data-action="save-set">Save</button></div><div class="hint" data-set-note="${n}" ${r.note?'':'hidden'} style="margin:0 0 10px">${r.note?`Set ${n} note: ${esc(r.note)}`:''}</div>`}).join('');
 const lastNote=rows.slice().sort((a,b)=>(b.updated_at||'').localeCompare(a.updated_at||''))[0]?.note||'';
 return `<article class="exercise-card" data-exercise="${esc(ex.id)}"><div class="exercise-header"><div class="exercise-title"><span class="exercise-index">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(ex.name)}</h3><div class="exercise-sub">${esc(ex.style)} · ${ex.rest}s rest</div></div></div><div class="exercise-qty"><strong>${esc(ex.reps)} reps</strong><small>${complete}/${target} sets logged</small></div></div><div class="exercise-detail">${esc(ex.tip)}</div><div class="sets-head"><span>SET</span><span>KG</span><span>REPS</span><span>RIR</span><span>DONE</span><span>LOG</span></div>${setRows}<div class="exercise-bottom"><button class="link-button" data-action="add-set" data-exid="${esc(ex.id)}">+ Add set</button><span class="small-status">${complete>0?`${complete} saved completed set${complete>1?'s':''}`:`Prescribed ${ex.sets} sets · adjust for recovery`}</span></div><div style="margin-top:11px"><label class="hint" for="note-${esc(ex.id)}">Note for the next set you save (clear to remove its note)</label><input id="note-${esc(ex.id)}" class="field set-note" data-exnote="${esc(ex.id)}" maxlength="5000" value="${esc(lastNote)}" placeholder="Tempo, grip, machine setting..."></div></article>`;
}
function trainingToolbar(){return `<div class="training-toolbar"><div class="day-tabs">${model.plan.days.map(day=>{const date=window.HybridSchedule.dateForDay(model.plan,selectedDate,day.day);return `<button class="day-btn ${date===selectedDate?'active':''}" data-day="${day.day}" aria-label="Open ${esc(day.day)} ${esc(shortDate(date))}">${day.short}<small>${esc(shortDate(date))}</small></button>`;}).join('')}</div><div class="date-control"><label for="training-date">Training date</label><input class="field" id="training-date" type="date" value="${selectedDate}"></div></div>`;}
function restTraining(){const next=window.HybridSchedule.nextSession(model.plan,selectedDate);return `<div class="page-head"><div><div class="overline">WEEKEND RECOVERY</div><h1>Rest & recovery.</h1><p class="page-sub">${esc(selectedDay)}, ${esc(friendly(selectedDate))} is a rest day. Your five lifting sessions run Monday to Friday.</p></div><span class="tag neutral">WEEK ${weekOf(selectedDate)} · REST</span></div>${trainingToolbar()}<section class="card recovery-card"><div class="overline">RECOVER FOR THE NEXT SESSION</div><h2>Give the work time to work.</h2><p class="hint">Keep Saturday and Sunday for recovery. Use your daily journal to record sleep, energy and how you feel.</p><div class="inline-flex">${button('Open daily journal →','journal')}<button class="btn btn-outline" data-session-date="${next.date}">Next: ${esc(next.day.short)} ${esc(shortDate(next.date))} →</button></div><hr class="separator"><h3>${esc(next.day.focus)}</h3><p class="hint">${esc(next.day.day)}, ${esc(friendly(next.date))} · ${next.day.cardio_target} min StairMaster · ${esc(next.day.cardio_intensity.toLowerCase())}</p></section>`;}
function train(){const week=weekOf(selectedDate),d=getDay(selectedDay);if(!d)return restTraining();const weekInfo=model.plan.weeks.find(w=>w.week===week);const cardio=recs('cardio').find(c=>c.date===selectedDate&&c.type==='StairMaster')||{};
 return `<div class="page-head"><div><div class="overline">SESSION BUILDER</div><h1>Training log.</h1><p class="page-sub">${sheetsMode?'Save a set and it is written directly to your Google Sheets workbook. Refresh Sheets to load edits made in the spreadsheet.':browserMode?'Save each set in this browser. Export a JSON backup regularly to keep a copy of your progress.':"Save each set directly to your local database; sync it to Google Sheets when you're ready."}</p></div><span class="tag">WEEK ${week} · ${esc(capWeek(week))}</span></div>
 ${trainingToolbar()}
 <div class="workout-intro"><div><div class="overline" style="color:var(--lime)">${esc(d.tag)}</div><h2>${esc(d.focus)}</h2><div class="hint">${d.exercises.length} exercises · ${weekdayTarget(d.day)} planned working sets · ${d.cardio_target} min StairMaster · ${esc(d.cardio_intensity.toLowerCase())}</div></div><span class="tag neutral">${esc(d.short)} · ${esc(friendly(selectedDate))}</span></div>
 <div class="alert" style="margin:0 0 15px"><strong>Week ${week}: ${esc(weekInfo.label)}</strong> — ${esc(weekInfo.rule)} Reduce the set count if needed, rather than forcing an intense session through excessive soreness.</div>
 <div class="exercise-list">${d.exercises.map((x,i)=>exerciseCard(x,i,week)).join('')}</div>
 <section class="card cardio-panel"><div class="card-head"><div><div class="overline">CONDITIONING / POST-WEIGHTS</div><h3 style="margin-top:7px">StairMaster + cardio</h3></div><span class="tag">TARGET ${d.cardio_target} MIN</span></div>
 <form id="cardio-form"><div class="form-grid"><div class="input-wrap"><label for="cardio-type">Machine / activity</label><select class="select" name="type" id="cardio-type"><option>StairMaster</option><option>Incline Walk</option><option>Bike</option><option>Other</option></select></div><div class="input-wrap"><label for="cardio-minutes">Minutes</label><input class="field" type="number" min="0" max="500" name="minutes" id="cardio-minutes" placeholder="e.g. 15" value="${esc(cardio.minutes||'')}"></div><div class="input-wrap"><label for="cardio-level">Machine level</label><input class="field" type="number" min="0" max="100" step="0.5" name="level" id="cardio-level" placeholder="e.g. 6" value="${esc(cardio.level||'')}"></div><div class="input-wrap"><label for="cardio-effort">Effort / 10</label><select class="select" name="effort" id="cardio-effort"><option value="">Choose</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${String(cardio.effort)==String(i+1)?'selected':''}>${i+1}</option>`).join('')}</select></div></div>
 <div class="input-wrap" style="margin-top:12px"><label for="cardio-note">Cardio notes (optional)</label><input class="field" id="cardio-note" name="note" value="${esc(cardio.note||'')}" placeholder="Breathing, intensity, how legs felt..."></div><div class="form-actions"><span class="hint" style="margin-right:auto">${d.cardio_intensity.toLowerCase()==='easy'?'Leg day finish: 10 minutes at an easy pace.':`Today's target: ${d.cardio_target} minutes at ${esc(d.cardio_intensity.toLowerCase())} intensity.`}</span><button class="btn btn-sm" type="submit">Save cardio →</button></div></form></section>`;
}
function localChart(points,metric='value'){
 const boxW=740,boxH=200,left=31,right=15,top=10,bottom=26,drawH=boxH-top-bottom,drawW=boxW-left-right;
 if(!points.length)return '<div class="no-data">Log a few workouts to see your progression chart.</div>';
 const max=Math.max(1,...points.map(x=>num(x[metric])))*1.13;
 const xy=points.map((v,i)=>({x:left+(points.length===1?.5:i/(points.length-1))*drawW,y:top+drawH-num(v[metric])/max*drawH}));
 const path=xy.map((p,i)=>`${i?'L':'M'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');
 return `<svg class="progress-chart" viewBox="0 0 ${boxW} ${boxH}" preserveAspectRatio="none" aria-label="Progress over recorded sessions" role="img"><defs><linearGradient id="chart-gradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c5f17c" stop-opacity=".24"/><stop offset="1" stop-color="#c5f17c" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(n=>`<line x1="${left}" x2="${boxW-right}" y1="${top+drawH*n}" y2="${top+drawH*n}" stroke="#344738" stroke-dasharray="3,5"/>`).join('')}<path d="${path} L ${xy[xy.length-1].x} ${top+drawH} L ${xy[0].x} ${top+drawH} Z" fill="url(#chart-gradient)"/><path d="${path}" fill="none" stroke="#c5f17c" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${xy.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4.3" fill="#c5f17c" stroke="#192819" stroke-width="2"/>`).join('')}</svg><div class="chart-legend"><span>${esc(points[0].date)}</span><span>${esc(points[points.length-1].date)}</span></div>`;
}
function dayIndex(iso){return Math.floor(Date.parse(iso+'T00:00:00Z')/86400000);}
function kgText(x){return x.toFixed(1)+' kg';}
function signedKg(x){const v=Math.round(x*10)/10;return (v>0?'+':v<0?'−':'')+Math.abs(v).toFixed(1)+' kg';}
function weightSeries(){const byDate={};for(const r of recs('checkins')){if(!r.date||!validNum(r.bodyweight_kg)||Number(r.bodyweight_kg)<=0)continue;const prev=byDate[r.date];if(!prev||(r.updated_at||'')>prev.updated_at)byDate[r.date]={date:r.date,kg:Number(r.bodyweight_kg),updated_at:r.updated_at||''};}
 const days=Object.values(byDate).sort((a,b)=>a.date.localeCompare(b.date));
 // Trend = mean of the weigh-ins in the 7 calendar days ending on each date, so missed days do not skew it.
 return days.map(p=>{const from=dayIndex(p.date)-6,win=days.filter(q=>q.date<=p.date&&dayIndex(q.date)>=from);return {...p,trend:win.reduce((a,q)=>a+q.kg,0)/win.length};});}
function weightChart(series){
 const W=1000,H=300,pad=16,inset=12,first=dayIndex(series[0].date),last=series[series.length-1],span=Math.max(1,dayIndex(last.date)-first);
 const vals=series.flatMap(p=>[p.kg,p.trend]);let lo=Math.min(...vals),hi=Math.max(...vals);const extra=Math.max(.3,(hi-lo)*.15);lo-=extra;hi+=extra;if(hi-lo<2){const mid=(hi+lo)/2;lo=mid-1;hi=mid+1;}
 const step=[.5,1,2,5,10,20].find(s=>(hi-lo)/s<=4)||50,ticks=[];for(let t=Math.ceil(lo/step)*step;t<=hi+1e-9;t+=step)ticks.push(t);
 const x=p=>series.length===1?W/2:inset+(dayIndex(p.date)-first)/span*(W-2*inset),y=v=>pad+(hi-v)/(hi-lo)*(H-2*pad);
 const line=series.map((p,i)=>`${i?'L':'M'}${x(p).toFixed(1)} ${y(p.trend).toFixed(1)}`).join(' ');
 return `<div class="weight-chart"><div class="weight-axis" aria-hidden="true">${ticks.map(t=>`<span style="top:${(y(t)/H*100).toFixed(2)}%">${t.toFixed(1)}</span>`).join('')}</div><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="Body weight from ${esc(friendly(series[0].date))} to ${esc(friendly(last.date))}. Latest ${kgText(last.kg)}, 7-day average ${kgText(last.trend)}."><defs><linearGradient id="weight-gradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c5f17c" stop-opacity=".2"/><stop offset="1" stop-color="#c5f17c" stop-opacity="0"/></linearGradient></defs>${ticks.map(t=>`<line class="weight-grid" x1="0" x2="${W}" y1="${y(t).toFixed(1)}" y2="${y(t).toFixed(1)}"/>`).join('')}${series.length>1?`<path d="${line} L${x(last).toFixed(1)} ${H} L${x(series[0]).toFixed(1)} ${H} Z" fill="url(#weight-gradient)"/><path class="weight-trend" d="${line}"/>`:''}${series.map(p=>`<path class="weight-dot${p===last?' latest':''}" d="M${x(p).toFixed(1)} ${y(p.kg).toFixed(1)}h0"><title>${esc(friendly(p.date))}: ${kgText(p.kg)}</title></path>`).join('')}</svg></div>
 <div class="chart-legend"><span>${esc(shortDate(series[0].date))}</span><span class="weight-key"><i class="key-dot"></i>Daily weigh-in<i class="key-line"></i>7-day trend</span><span>${esc(shortDate(last.date))}</span></div>`;
}
function weightStat(title,value,tail){return `<div class="weight-stat"><small>${title}</small><strong>${value}</strong><span>${tail}</span></div>`;}
function weightCard(inJournal){const series=weightSeries(),style=inJournal?'margin-top:18px':'margin-bottom:18px';
 const head=`<div class="card-head"><div><h3>Body weight trend</h3><p class="hint" style="margin:5px 0 0">Daily weigh-ins from your journal, with a 7-day rolling average</p></div><span class="mini-badge">${series.length} WEIGH-IN${series.length===1?'':'S'}</span></div>`;
 if(!series.length)return `<section class="card" style="${style}">${head}<div class="no-data">${inJournal?'Save your body weight in a daily check-in to start your trend.':'Log your body weight in the Daily journal each day to see your trend here.'}</div>${inJournal?'':`<div style="margin-top:14px">${button('Open daily journal →','journal','btn-outline btn-sm')}</div>`}</section>`;
 const last=series[series.length-1],weekAgo=series.slice().reverse().find(p=>dayIndex(p.date)<=dayIndex(last.date)-7);
 return `<section class="card" style="${style}">${head}<div class="weight-stats">${weightStat('LATEST',kgText(last.kg),esc(friendly(last.date)))}${weightStat('7-DAY AVERAGE',kgText(last.trend),'Your trend weight')}${weightStat('LAST 7 DAYS',weekAgo?signedKg(last.trend-weekAgo.trend):'–',weekAgo?'Change in trend':'Needs 8 days of weigh-ins')}${weightStat('SINCE START',series.length>1?signedKg(last.trend-series[0].trend):'–','Since '+esc(shortDate(series[0].date)))}</div>${weightChart(series)}</section>`;}
function progress(){const complete=recs('sets').filter(done), cardio=recs('cardio'), eids=model.plan.days.flatMap(d=>d.exercises.map(e=>({id:e.id,name:e.name,day:d.short})));
 const chosen=(focusExercise&&eids.some(x=>x.id===focusExercise))?focusExercise:eids[0].id;
 const exercise=eids.find(x=>x.id===chosen), subset=complete.filter(s=>s.exercise_id===chosen).sort((a,b)=>a.date.localeCompare(b.date));
 const datapoints=Object.values(subset.reduce((a,row)=>{if(!a[row.date])a[row.date]={date:row.date,value:0,total:0};a[row.date].value=Math.max(a[row.date].value,num(row.weight_kg));a[row.date].total+=num(row.weight_kg)*num(row.reps);return a;},{}));
 const maxWeights=Object.values(complete.reduce((a,r)=>{const k=r.exercise_id; if(!a[k]||num(r.weight_kg)>num(a[k].weight_kg))a[k]=r;return a;},{})).sort((a,b)=>num(b.weight_kg)-num(a.weight_kg)).slice(0,6);
 const trainingDays=new Set(complete.map(s=>s.date)).size;
 const volume=complete.reduce((a,r)=>a+num(r.reps)*num(r.weight_kg),0);
 const cardioMin=cardio.reduce((a,c)=>a+num(c.minutes),0);
 return `<div class="page-head"><div><div class="overline">ANALYSE THE WORK</div><h1>Progress.</h1><p class="page-sub">No guesswork. See your best recorded loads, training volume, cardio minutes and consistency.</p></div><span class="tag neutral">ALL-TIME LOGS</span></div>
 <div class="stats">${kpi('COMPLETED SETS',nfmt(complete.length),'All time')}${kpi('TRAINING DAYS',nfmt(trainingDays),'Unique recorded dates')}${kpi('TOTAL VOLUME',nfmt(volume),'kg × reps')}${kpi('CARDIO MINUTES',nfmt(cardioMin),'All activities')}</div>
 ${weightCard(false)}
 <div class="content-grid"><div class="grid-gap"><section class="card"><div class="card-head"><div><h3>Exercise progression</h3><p class="hint" style="margin:5px 0 0">Top completed-set load by training date</p></div></div><div class="input-wrap"><label for="exercise-chart-select">Choose exercise</label><select class="select" id="exercise-chart-select">${eids.map(e=>`<option value="${esc(e.id)}" ${e.id===chosen?'selected':''}>${esc(e.name)} · ${esc(e.day)}</option>`).join('')}</select></div><div style="padding-top:20px">${localChart(datapoints)}</div><p class="hint">Machines differ in resistance. Compare the same exercise and machine, not different machines or movements.</p></section>
 <section class="card"><div class="card-head"><h3>Recent completed sets</h3><span class="mini-badge">LAST 8</span></div>${complete.length?`<div class="history-list">${complete.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(r=>`<div class="history-row"><div><strong>${esc(r.exercise)}</strong><small>${friendly(r.date)} · set ${esc(r.set_number)}</small></div><div><strong>${esc(r.weight_kg||'0')} kg</strong></div><div>${esc(r.reps)} reps</div></div>`).join('')}</div>`:'<div class="no-data">Your completed sets will appear here.</div>'}</section></div>
 <section class="card"><div class="card-head"><h3>Best logged weights</h3><span class="mini-badge">PERSONAL BESTS</span></div>${maxWeights.length?`<div class="grid-gap">${maxWeights.map((r,i)=>`<div class="pr"><small>${String(i+1).padStart(2,'0')} / ${esc(r.exercise)}</small><strong>${esc(r.weight_kg)} kg</strong><small>${esc(r.reps)} reps · ${friendly(r.date)}</small></div>`).join('')}</div>`:'<div class="no-data">Your strongest logged sets will appear as you train.</div>'}
 <hr class="separator"><div class="overline">ABOUT VOLUME</div><p class="hint">Volume shown here is weight × reps on completed sets. It is an internal consistency metric, not a direct measure of muscle gain. Excludes zero-weight bodyweight exercises.</p></section></div>`;
}
function journal(){const check=recs('checkins').find(r=>r.id===`checkin__${selectedDate}`)||recs('checkins').find(r=>r.date===selectedDate)||{};
 const notes=recs('notes').slice().sort((a,b)=>b.date.localeCompare(a.date)||b.updated_at.localeCompare(a.updated_at));
 return `<div class="page-head"><div><div class="overline">THE RECOVERY SIDE OF GROWTH</div><h1>Daily journal.</h1><p class="page-sub">Track your body weight, sleep, energy and the small details that tell you whether training is working.</p></div><span class="tag neutral">${sheetsMode?'DIRECT TO GOOGLE SHEETS':browserMode?'PRIVATE BROWSER DATA':'LOCAL + GOOGLE SHEETS'}</span></div>
 <div class="training-toolbar"><div class="date-control"><label for="journal-date">Check-in date</label><input class="field" type="date" id="journal-date" value="${selectedDate}"></div></div>
 <div class="journal-grid"><section class="card"><div class="card-head"><h3>Daily check-in</h3><span class="mini-badge">${esc(friendly(selectedDate))}</span></div>
 <form id="checkin-form"><div class="form-grid" style="grid-template-columns:repeat(2,1fr)"><div class="input-wrap"><label for="bodyweight">Body weight (kg)</label><input class="field" type="number" step="0.1" min="0" max="500" id="bodyweight" name="bodyweight_kg" placeholder="e.g. 70.2" value="${esc(check.bodyweight_kg||'')}"></div><div class="input-wrap"><label for="sleep">Hours slept</label><input class="field" type="number" step="0.5" min="0" max="24" id="sleep" name="sleep_hours" placeholder="e.g. 7.5" value="${esc(check.sleep_hours||'')}"></div><div class="input-wrap"><label for="energy">Energy (1–5)</label><select class="select" id="energy" name="energy"><option value="">Choose</option>${Array.from({length:5},(_,i)=>`<option value="${i+1}" ${String(check.energy)==String(i+1)?'selected':''}>${i+1} / 5</option>`).join('')}</select></div><div class="input-wrap"><label for="duration">Workout duration (min)</label><input class="field" type="number" min="0" max="500" id="duration" name="duration_min" placeholder="e.g. 65" value="${esc(check.duration_min||'')}"></div></div><div class="input-wrap" style="margin-top:15px"><label for="check-note">Recovery notes</label><textarea class="area" id="check-note" name="note" placeholder="Muscle soreness, meals, stress, how your session felt...">${esc(check.note||'')}</textarea></div><div class="form-actions"><button class="btn" type="submit">Save check-in →</button></div></form></section>
 <section class="card"><div class="card-head"><h3>Add a training note</h3><span class="mini-badge">FREEFORM</span></div><form id="note-form"><div class="input-wrap"><label for="note-category">Category</label><select class="select" name="category" id="note-category"><option>Training</option><option>Recovery</option><option>Nutrition</option><option>Win</option><option>Question</option></select></div><div class="input-wrap" style="margin-top:15px"><label for="note-text">What happened?</label><textarea class="area" name="note" id="note-text" required maxlength="5000" placeholder="Chest press at 18kg felt much more controlled. Next time aim for..." style="min-height:168px"></textarea></div><div class="form-actions"><button class="btn" type="submit">Add note →</button></div></form></section></div>
 ${weightCard(true)}
 <section class="card" style="margin-top:18px"><div class="card-head"><h3>Notes timeline</h3><span class="mini-badge">${notes.length} NOTES</span></div>${notes.length?notes.map(note=>`<article class="note-card"><div><small>${friendly(note.date)} · ${esc(note.category)}</small><p>${esc(note.note)}</p></div><button class="btn btn-danger btn-sm" data-delete-note="${esc(note.id)}" aria-label="Delete note">Delete</button></article>`).join(''):'<div class="no-data">No notes yet. Log a breakthrough, recovery observation or question above.</div>'}</section>`;
}
function sheetsSettings(){return `<div class="page-head"><div><div class="overline">YOUR WORKBOOK / CONNECTED</div><h1>Google Sheets.</h1><p class="page-sub">Your workbook is the live source for this dashboard. Sets, cardio, check-ins and notes save directly to their spreadsheet tabs.</p></div><span class="tag">CONNECTED</span></div><div class="content-grid"><section class="card"><div class="card-head"><h3>Your workout workbook</h3><span class="mini-badge">DIRECT SAVE</span></div>${model.sheet_url?`<p><a class="sheet-link" href="${esc(model.sheet_url)}" target="_blank" rel="noopener noreferrer">Open THE HYBRID workout spreadsheet ↗</a></p>`:''}<p class="hint">Press Save after entering a set, cardio session or daily check-in. A confirmation appears after Google Sheets accepts the update. New notes and deletions are also written immediately.</p><hr class="separator"><div class="inline-flex"><button class="btn" data-action="refresh-sheets">↻ Refresh Sheets</button><span class="hint">Load the latest entries and spreadsheet edits.</span></div></section><section class="card"><div class="card-head"><h3>One workbook, wherever you train</h3><span class="mini-badge">GOOGLE SHEETS</span></div><p class="hint">Open this connected dashboard with your authorised Google account on your phone or computer. Your saved workout history comes from the same workbook each time.</p><p class="hint">Edit records in the spreadsheet when needed, then click Refresh Sheets here. Keep the existing column headers and record IDs so each entry stays matched to its workout.</p><div class="alert">This dashboard needs an internet connection to read and save your workbook. Wait for the saved confirmation before leaving the page.</div></section></div>`;}
function browserSettings(){const connectedUrl=connectedDashboardUrl();return `<div class="page-head"><div><div class="overline">YOUR TRAINING / YOUR DATA</div><h1>Backup & data.</h1><p class="page-sub">Your workout logs stay in this browser on this device. Keep a JSON backup so you can restore or move them when needed.</p></div><span class="tag neutral">PRIVATE BY DEFAULT</span></div>
 <div class="content-grid"><section class="card"><div class="card-head"><h3>Keep your progress safe</h3><span class="mini-badge">JSON BACKUPS</span></div><div class="inline-flex"><button class="btn" data-action="export">↓ Export JSON backup</button><button class="btn btn-quiet" data-action="choose-import">↑ Restore JSON backup</button><input type="file" id="backup-input" accept="application/json,.json" hidden></div><p class="hint" style="margin-top:17px">Exports include your sets, cardio, journal notes and daily check-ins. Restore merges a valid backup into this browser; matching record IDs are updated.</p><div class="alert">Clearing this site's data, using a different browser or device, or ending a private browsing session can remove access to your logs. Export regularly and save the file somewhere you trust.</div></section>
 <section class="card"><div class="card-head"><h3>Stored on this device</h3><span class="mini-badge">BROWSER STORAGE</span></div><p class="hint">The hosted dashboard stores your entries locally using your browser's site storage. Workout records are not uploaded to GitHub or shared with other visitors. Another browser or device has its own separate records.</p><hr class="separator">${connectedUrl?`<h3>Your connected Google Sheets dashboard</h3><p class="hint">Open the connected dashboard to read your workbook and save workouts directly to Google Sheets. This browser's local logs remain available here.</p><a class="btn" href="${esc(connectedUrl)}" target="_blank" rel="noopener noreferrer">Open connected dashboard ↗</a>`:'<h3>Want Google Sheets sync?</h3><p class="hint">Two-way Google Sheets sync is supported by the Python version in this project\'s repository. Download it, run it on your computer, and follow the README to connect your own Google account. Export here and restore in the Python version to move your logs.</p>'}</section></div>`;}
function settings(){if(sheetsMode)return sheetsSettings();if(browserMode)return browserSettings();return `<div class="page-head"><div><div class="overline">BACKUP / CONNECTIVITY</div><h1>Google Sheets sync.</h1><p class="page-sub">Data lives on your computer in SQLite. Connect Google Sheets for an editable cloud copy and two-way updates.</p></div><span class="tag ${model.connected?'':'neutral'}">${model.connected?'GOOGLE TOKEN PRESENT':'GOOGLE NOT CONNECTED'}</span></div>
 <div class="content-grid"><section class="card"><div class="card-head"><h3>Cloud connection</h3><span class="mini-badge">TWO-WAY SYNC</span></div><div class="overline">${model.sheet_url?'YOUR CONFIGURED WORKBOOK':'CONNECT YOUR OWN WORKBOOK'}</div><p>${model.sheet_url?`<a class="sheet-link" href="${esc(model.sheet_url)}" target="_blank" rel="noopener noreferrer">Open your workout spreadsheet ↗</a>`:'<span class="hint">Set your own <code>spreadsheet_id</code> in <code>config.json</code>, then restart the local server. The README explains how to prepare your workbook.</span>'}</p><div class="hint">Training plan is read-only; workout sets, cardio, notes and check-ins sync in both directions after setup.</div><hr class="separator"><div class="inline-flex"><button class="btn" data-action="sync">↻ Sync now</button><span class="hint">${model.last_sync?'Last successful sync: '+esc(new Date(model.last_sync).toLocaleString('en-GB')):'No successful sync recorded yet.'}</span></div><div class="alert">Google requires separate OAuth approval for an application running on your computer. Your ChatGPT Google Drive connection cannot be silently reused by this localhost app.</div><hr class="separator"><div class="checkbox-label"><input type="checkbox" id="auto-sync-toggle" ${getAutoSync()?'checked':''}> <label for="auto-sync-toggle">Automatically sync after saving a set or note (requires OAuth)</label></div></section>
 <section class="card"><h3>Connect once on your computer</h3><div class="setting-step"><span class="step-number">1</span><div><strong>Create OAuth credentials</strong><p>In <a class="sheet-link" href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer">Google Cloud Console</a>, create or choose a project. Enable Google Sheets API. Configure the OAuth consent screen and create an <strong>OAuth client ID → Desktop app</strong>. Add yourself as a test user if applicable.</p></div></div><div class="setting-step"><span class="step-number">2</span><div><strong>Save your client JSON</strong><p>Download the OAuth client JSON and rename it <code>credentials.json</code>. Put it beside <code>server.py</code> on your computer. Do not share or upload it.</p></div></div><div class="setting-step"><span class="step-number">3</span><div><strong>Authorise locally</strong><p>Run <code>python -m pip install -r requirements.txt</code> then <code>python connect_google.py</code>. Sign in with the Google account that can edit your own workbook.</p></div></div><div class="setting-step"><span class="step-number">4</span><div><strong>Configure and sync your workbook</strong><p>Prepare your own Google Sheets workbook using the README, set its <code>spreadsheet_id</code> in <code>config.json</code>, and restart <code>python server.py</code>. Return here and click Sync now.</p></div></div></section>
 </div><section class="card" style="margin-top:18px"><div class="card-head"><h3>Data ownership and backup</h3><span class="tag neutral">YOUR DATA</span></div><div class="inline-flex"><button class="btn btn-outline" data-action="export">↓ Export JSON backup</button><button class="btn btn-quiet" data-action="choose-import">↑ Restore JSON backup</button><input type="file" id="backup-input" accept="application/json,.json" hidden></div><p class="hint" style="margin-top:17px">The app listens only on <code>127.0.0.1</code> and stores records in <code>data/workouts.sqlite3</code>. Google OAuth tokens stay in <code>data/token.json</code>. Back up the JSON file regularly. If a record is edited in both places before syncing, the local version wins; the Google version is backed up to <code>data/sync_conflicts.json</code>.</p></section>`;
}
async function write(kind,record){const data=await api(`/api/records/${kind}`,{method:'POST',body:JSON.stringify(record)});if(data?.ok!==true||!data.record||typeof data.record!=='object'||Array.isArray(data.record)||data.record.id!==record.id||data.record.date!==record.date)throw Error(`${sheetsMode?'Google Sheets':'The tracker'} did not confirm this record was saved. Please refresh and check before trying again.`);model.records[kind]=model.records[kind].filter(r=>r.id!==record.id).concat(data.record);if(sheetsMode){lastSheetSave=new Date().toISOString();updateTop();}return data.record;}
function maybeAutoSync(){if(!sheetsMode&&model.connected&&getAutoSync())setTimeout(()=>syncNow(true),1200);}
async function saveSet(button){const row=button.closest('.set-row'),card=row.closest('.exercise-card'),exid=card.dataset.exercise;const ex=getDay(selectedDay).exercises.find(e=>e.id===exid),n=row.dataset.set;
 const weight=row.querySelector('[data-field=weight_kg]').value.trim(),reps=row.querySelector('[data-field=reps]').value.trim(),rir=row.querySelector('[data-field=rir]').value.trim(),completed=row.querySelector('[data-field=completed]').checked;
 if(completed && (!reps || Number(reps)<=0)){toast('Enter reps before marking a set complete.',true);return;}
 if([weight,reps,rir].some(v=>v!==''&&(!Number.isFinite(+v)||Number(v)<0))){toast('Enter nonnegative numbers for weight, reps and RIR.',true);return;}
 if((weight!==''&&Number(weight)>9999)||(reps!==''&&(!Number.isInteger(Number(reps))||Number(reps)>9999))){toast('Weight must be 0–9999 kg and reps a whole number from 0–9999.',true);return;}
 if(rir!==''&&(!Number.isInteger(Number(rir))||Number(rir)>10)){toast('RIR should be a whole number from 0–10.',true);return;}
 const old=getSets(selectedDate,exid).find(r=>num(r.set_number)==num(n))||{};
 const note=card.querySelector('[data-exnote]').value.trim();
 const record={...old,id:old.id||setId(selectedDate,exid,n),date:selectedDate,day:selectedDay,exercise_id:exid,exercise:ex.name,set_number:n,weight_kg:weight,reps,rir,completed:completed?'TRUE':'FALSE',note};
 try{button.disabled=true;await write('sets',record);const complete=getSets(record.date,exid).filter(done).length;card.querySelector('.exercise-qty small').textContent=`${complete}/${ex.sets} sets logged`;card.querySelector('.small-status').textContent=`${complete} saved completed set${complete===1?'':'s'}`;let savedNote=card.querySelector(`[data-set-note="${n}"]`);if(!savedNote){savedNote=document.createElement('div');savedNote.className='hint';savedNote.dataset.setNote=n;savedNote.style.margin='0 0 10px';row.after(savedNote);}savedNote.hidden=!note;savedNote.textContent=note?`Set ${n} note: ${note}`:'';button.textContent='Saved';button.disabled=false;toast(`${ex.name} · set ${n} ${sheetsMode?'saved to Google Sheets':'saved locally'}`);maybeAutoSync();}catch(e){button.disabled=false;toast(e.message,true);}
}
async function refreshSheets(){if(!sheetsMode||syncing)return;if(pendingSheetWrites){toast('Wait for your current save to finish, then refresh Sheets.');return;}const controls='[data-action=refresh-sheets],#view input,#view select,#view textarea,#view [data-action=save-set],#view [type=submit],#view [data-delete-note]';syncing=true;all(controls).forEach(control=>control.disabled=true);try{lastSheetSave=null;await load();toast('Latest Google Sheets entries loaded.');}catch(error){toast('Could not refresh Google Sheets: '+error.message,true);}finally{syncing=false;all(controls).forEach(control=>control.disabled=false);}}
async function syncNow(silent=false){if(sheetsMode)return refreshSheets();if(syncing)return;if(!model.connected){if(!silent){nav('settings');toast('Google is not connected. Follow the 4 steps to authorise sync.',true);}return;}syncing=true;const buttons=all('[data-action=sync]');buttons.forEach(b=>b.disabled=true);try{const r=await api('/api/sync',{method:'POST',body:'{}'});await load();if(!silent||r.conflicts>0)toast(`Synced: ${r.pulled} pulled, ${r.pushed} pushed${r.conflicts?' · '+r.conflicts+' conflict(s) backed up':''}.`);}catch(e){if(!silent)toast('Sync failed: '+e.message,true);else console.warn('Auto sync:',e.message);}finally{syncing=false;all('[data-action=sync]').forEach(b=>b.disabled=false);}}
function formDrafts(except){return all('#view form').filter(form=>form.id!==except).map(form=>({id:form.id,values:Array.from(form.elements).filter(field=>field.name).map(field=>({name:field.name,value:field.value}))}));}
function restoreFormDrafts(drafts){for(const draft of drafts){const form=document.getElementById(draft.id);if(form)for(const field of draft.values)if(form.elements[field.name])form.elements[field.name].value=field.value;}}
async function saveForm(form,kind,record){const button=form.querySelector('[type=submit]');button.disabled=true;try{await write(kind,record);if(form.isConnected&&(kind==='notes'||kind==='checkins')){const drafts=formDrafts(form.id);draw();restoreFormDrafts(drafts);}button.disabled=false;toast((kind==='cardio'?'Cardio session saved':kind==='checkins'?'Check-in saved':'Note added')+(sheetsMode?' to Google Sheets':' locally'));maybeAutoSync();}catch(e){toast(e.message,true);button.disabled=false;}}
function uniqueId(){return 'note__'+Date.now()+'__'+Math.random().toString(36).slice(2,10);}
async function exportBackup(){try{const backup=await api('/api/export'),blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`hybrid-workout-backup-${localISO()}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('JSON backup downloaded. Keep it somewhere safe.');}catch(error){toast('Could not export backup: '+error.message,true);}}
async function processForm(form){const obj=Object.fromEntries(new FormData(form).entries());if(form.id==='cardio-form'){const old=recs('cardio').find(record=>record.date===selectedDate&&record.type===obj.type);return saveForm(form,'cardio',{id:old?.id||`${selectedDate}__${obj.type.toLowerCase().replace(/\W+/g,'_')}`,date:selectedDate,day:selectedDay,...obj});}
 if(form.id==='checkin-form'){const old=recs('checkins').find(record=>record.id===`checkin__${selectedDate}`)||recs('checkins').find(record=>record.date===selectedDate);return saveForm(form,'checkins',{id:old?.id||`checkin__${selectedDate}`,date:selectedDate,day:dayFor(selectedDate),...obj});}
 if(form.id==='note-form'){if(!obj.note?.trim()){toast('Add a note first.',true);return;}return saveForm(form,'notes',{id:uniqueId(),date:selectedDate,day:dayFor(selectedDate),...obj});}}
document.addEventListener('submit',e=>{if(['cardio-form','checkin-form','note-form'].includes(e.target.id)){e.preventDefault();processForm(e.target);}});
document.addEventListener('click',async e=>{
 const n=e.target.closest('[data-nav]');if(n){e.preventDefault();nav(n.dataset.nav);return;}
 const session=e.target.closest('[data-session-date]');if(session){selectedDate=session.dataset.sessionDate;selectedDay=dayFor(selectedDate);nav('train');return;}
 const day=e.target.closest('[data-day]');if(day){selectedDate=window.HybridSchedule.dateForDay(model.plan,selectedDate,day.dataset.day);selectedDay=dayFor(selectedDate);draw();return;}
 const jump=e.target.closest('[data-jump-day]');if(jump){selectedDate=window.HybridSchedule.dateForDay(model.plan,selectedDate,jump.dataset.jumpDay);selectedDay=dayFor(selectedDate);nav('train');return;}
 const save=e.target.closest('[data-action=save-set]');if(save){await saveSet(save);return;}
 const add=e.target.closest('[data-action=add-set]');if(add){const card=add.closest('.exercise-card'),rows=card.querySelectorAll('.set-row'),n=rows.length+1;if(n>30)return toast('Maximum 30 sets per exercise.',true);const ex=getDay(selectedDay).exercises.find(x=>x.id===card.dataset.exercise);const wrap=document.createElement('div');wrap.innerHTML=`<div class="set-row" data-set="${n}" data-exid="${esc(ex.id)}"><div class="set-num">${n}</div><input class="field" type="number" min="0" step="0.5" placeholder="kg" data-field="weight_kg" aria-label="Weight in kilograms"><input class="field" type="number" min="0" placeholder="reps" data-field="reps" aria-label="Reps"><input class="field" type="number" min="0" max="10" placeholder="RIR" data-field="rir" aria-label="Reps in reserve"><input class="set-check" type="checkbox" data-field="completed" aria-label="Mark set complete"><button class="set-save" data-action="save-set">Save</button></div>`;card.querySelector('.exercise-bottom').before(wrap.firstElementChild);toast('Extra set added — enter values and save.');return;}
 const act=e.target.closest('[data-action]');if(act){if(act.dataset.action==='refresh-sheets')return refreshSheets();if(act.dataset.action==='sync')return syncNow();if(act.dataset.action==='export')return exportBackup();if(act.dataset.action==='choose-import'){return $('#backup-input')?.click();}}
 const del=e.target.closest('[data-delete-note]');if(del){if(!confirm(sheetsMode?'Delete this note from Google Sheets?':browserMode?'Delete this note from this browser?':'Delete this note? Deletion will sync to Google Sheets on your next sync.'))return;try{const result=await api('/api/records/notes/'+encodeURIComponent(del.dataset.deleteNote),{method:'DELETE'});if(result?.deleted!==true)throw Error('The note deletion was not confirmed. Refresh and check your notes before trying again.');model.records.notes=model.records.notes.filter(x=>x.id!==del.dataset.deleteNote);if(sheetsMode){lastSheetSave=new Date().toISOString();updateTop();}if(del.isConnected){const drafts=formDrafts();draw();restoreFormDrafts(drafts);}toast(sheetsMode?'Note deleted from Google Sheets':'Note deleted locally');maybeAutoSync();}catch(ex){toast(ex.message,true);}return;}
});
document.addEventListener('change',async e=>{
 if(e.target.id==='training-date'||e.target.id==='journal-date'){const date=e.target.value||localISO();try{selectedDay=dayFor(date);selectedDate=date;draw();}catch(error){toast(error.message,true);}return;}
 if(e.target.id==='exercise-chart-select'){focusExercise=e.target.value;draw();return;}
 if(e.target.id==='auto-sync-toggle'){setAutoSync(e.target.checked);toast(e.target.checked?'Auto sync enabled after saving':'Auto sync disabled');return;}
 if(e.target.id==='backup-input' && e.target.files?.[0]){try{const obj=JSON.parse(await e.target.files[0].text());if(!confirm(`Import backup records into ${browserMode?'this browser':'the local database'}? Matching IDs will be updated.`))return;const out=await api('/api/import',{method:'POST',body:JSON.stringify(obj)});await load();toast('Backup restored: '+Object.values(out.imported).reduce((a,b)=>a+b,0)+' records.');}catch(ex){toast('Could not restore backup: '+ex.message,true);}finally{e.target.value='';}return;}
 if(e.target.id==='cardio-type'){const c=recs('cardio').find(x=>x.date===selectedDate&&x.type===e.target.value);const f=e.target.form;if(c){for(const key of ['minutes','level','effort','note'])if(f.elements[key])f.elements[key].value=c[key]||'';}else{for(const key of ['minutes','level','effort','note'])if(f.elements[key])f.elements[key].value='';}return;}
});
window.addEventListener('hashchange',()=>{const next=location.hash.replace('#','');if(['dashboard','train','progress','journal','settings'].includes(next)&&next!==view)nav(next);});
document.addEventListener('input',event=>{const row=event.target.closest('.set-row');if(row)row.querySelector('[data-action=save-set]').textContent='Save';});
(async()=>{configureBrowserUI();try{const hash=location.hash.slice(1);if(['dashboard','train','progress','journal','settings'].includes(hash))view=hash;all('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));await load();}catch(e){$('#view').innerHTML=sheetsMode?`<div class="no-data">Could not connect to Google Sheets: ${esc(e.message)} Sign in with your authorised Google account and try Refresh Sheets.</div>`:browserMode?`<div class="no-data">Could not load your dashboard: ${esc(e.message)}</div>`:`<div class="no-data">Cannot reach the local tracker: ${esc(e.message)}. Start <code>python server.py</code> and refresh.</div>`;}})();
